import { queryOptions } from "@tanstack/react-query"

import { getAddresses } from "@/features/checkout-address/api/get-addresses.api"
import { addressKeys } from "@/features/checkout-address/api/query-keys"

export const addressesQueryOptions = queryOptions({
  queryKey: addressKeys.all,
  queryFn: getAddresses,
  // The dummy list only changes in this cache. With a real API, remove this line.
  staleTime: Infinity
})

import { DUMMY_ADDRESSES } from "@/features/checkout-address/constants/addresses.constants"
import type { Address } from "@/features/checkout-address/schemas/address.schema"

/** No request yet: replace the body with `api.get(ADDRESSES_PATH, { schema })` for your API. */
export async function getAddresses(): Promise<Address[]> {
  return DUMMY_ADDRESSES
}

export const addressKeys = {
  all: ["addresses"] as const
}

import { http, HttpResponse } from "msw/http"
import { describe, expect, it } from "vitest"

import { siteConfig } from "@/config/site.config"

import { saveAddress } from "@/features/checkout-address/api/save-address.api"
import { ADDRESSES_PATH } from "@/features/checkout-address/constants/addresses.constants"
import { server } from "@/test/server"

const input = {
  addressName: "Home",
  firstName: "Ömer",
  lastName: "Gülçiçek",
  phone: "5550000000",
  addressLine: "Örnek Caddesi",
  provinceCode: "34",
  province: "İSTANBUL",
  district: "KADIKÖY",
  neighbourhood: "CAFERAĞA MAH.",
  postalCode: "34710",
  isDefault: false,
  addressType: "individual" as const,
  companyName: "",
  taxNumber: "",
  taxOffice: ""
}

describe("saveAddress", () => {
  it("posts a new address with its country", async () => {
    let body: unknown
    server.use(
      http.post(`${siteConfig.apiUrl}${ADDRESSES_PATH}/add`, async ({ request }) => {
        body = await request.json()
        return HttpResponse.json({ id: 209 }, { status: 201 })
      })
    )

    const saved = await saveAddress(input)

    expect(body).toEqual({ ...input, countryCode: "TR" })
    expect(saved).toMatchObject(input)
    expect(saved.id).toEqual(expect.any(Number))
  })

  it("puts an edited address and keeps its id", async () => {
    let method = ""
    server.use(
      http.put(`${siteConfig.apiUrl}${ADDRESSES_PATH}/1`, ({ request }) => {
        method = request.method
        return HttpResponse.json({ id: 1 })
      })
    )

    await expect(saveAddress(input, 7)).resolves.toEqual({ ...input, id: 7 })
    expect(method).toBe("PUT")
  })
})

import { api } from "@/lib/api"

import {
  ADDRESSES_PATH,
  COUNTRY_CODE
} from "@/features/checkout-address/constants/addresses.constants"
import { savedAddressSchema } from "@/features/checkout-address/schemas/address.schema"
import type { Address, AddressFormInput } from "@/features/checkout-address/schemas/address.schema"

/**
 * An address carries no shipping or billing type: it joins the address book, and the order later
 * says which one is which. The request is real, but DummyJSON keeps nothing and answers every new
 * user with the same id, so the result is built from the input. With your API, return its answer.
 */
export async function saveAddress(input: AddressFormInput, id?: number): Promise<Address> {
  const body = { ...input, countryCode: COUNTRY_CODE }

  await (id === undefined
    ? api.post(`${ADDRESSES_PATH}/add`, body, { schema: savedAddressSchema })
    : api.put(`${ADDRESSES_PATH}/1`, body, { schema: savedAddressSchema }))

  return { ...input, id: id ?? Date.now() }
}

import { formatAddress } from "@virastack/address"
import { createMask } from "@virastack/mask"
import { useTranslations } from "next-intl"

import { Badge } from "@/components/ui/badge"
import { PHONE_MASKS } from "@/features/checkout-address/constants/addresses.constants"
import type { Address } from "@/features/checkout-address/schemas/address.schema"

const phoneMask = createMask(PHONE_MASKS.phone)

export function AddressDetails({ address }: { address: Address }) {
  const t = useTranslations("CheckoutAddress")

  return (
    <span className="flex min-w-0 flex-col gap-1 text-sm">
      <span className="flex flex-wrap items-center gap-2 font-medium">
        {address.addressName}
        {address.isDefault ? <Badge variant="secondary">{t("default_badge")}</Badge> : null}
      </span>
      <span>
        {address.firstName} {address.lastName} · {phoneMask.format(address.phone)}
      </span>
      <span className="text-pretty text-muted-foreground">
        {address.addressLine}, {formatAddress(address, { postalCode: true })}
      </span>
      {address.addressType === "corporate" ? (
        <span className="text-pretty text-muted-foreground">
          {address.companyName} ·{" "}
          {t("tax_summary", { office: address.taxOffice, number: address.taxNumber })}
        </span>
      ) : null}
    </span>
  )
}

"use client"

import type { ReactNode } from "react"

import { zodResolver } from "@hookform/resolvers/zod"
import { useViraAddress } from "@virastack/address"
import { maskResolver, useViraMask } from "@virastack/mask"
import { useTranslations } from "next-intl"
import { Controller, useForm, useWatch } from "react-hook-form"
import type { UseFormReturn } from "react-hook-form"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Field, FieldError, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue
} from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import { PHONE_MASKS, TAX_MASKS } from "@/features/checkout-address/constants/addresses.constants"
import { useSaveAddress } from "@/features/checkout-address/hooks/use-save-address"
import {
  ADDRESS_TAX_TYPES,
  createAddressFormSchema
} from "@/features/checkout-address/schemas/address.schema"
import type {
  Address,
  AddressFormInput,
  AddressType
} from "@/features/checkout-address/schemas/address.schema"

const EMPTY_VALUES: AddressFormInput = {
  addressName: "",
  firstName: "",
  lastName: "",
  phone: "",
  addressLine: "",
  provinceCode: "",
  province: "",
  district: "",
  neighbourhood: "",
  postalCode: "",
  isDefault: false,
  addressType: "individual",
  companyName: "",
  taxNumber: "",
  taxOffice: ""
}

const FORM_MASKS = { ...PHONE_MASKS, ...TAX_MASKS }

const ADDRESS_NAMES = {
  province: "province",
  district: "district",
  neighbourhood: "neighbourhood",
  postalCode: "postalCode",
  provinceCode: "provinceCode"
} as const

type AddressFormProps = {
  /** Sets the browser's autofill section, so it offers the right saved address. */
  type: AddressType
  /** Fills the form to edit this address; `null` starts it empty. */
  address: Address | null
  onSaved: (saved: Address) => void
}

export function AddressForm({ type, address, onSaved }: AddressFormProps) {
  const t = useTranslations("CheckoutAddress")
  const saveAddress = useSaveAddress()
  const form = useForm<AddressFormInput>({
    resolver: maskResolver(FORM_MASKS, zodResolver(createAddressFormSchema(t))),
    defaultValues: address ?? EMPTY_VALUES
  })
  const { errors, isSubmitted, isSubmitting } = form.formState
  const addressType = useWatch({ control: form.control, name: "addressType" })
  // A failed submit focuses the first registered field with an error, and the mask registers the
  // phone while rendering, so the fields above it on screen must register first.
  form.register("firstName")
  form.register("lastName")
  const { phone } = useViraMask(form, PHONE_MASKS)
  const {
    provinces,
    districts,
    neighbourhoods,
    getProvinceProps,
    getDistrictProps,
    getNeighbourhoodProps,
    getPostalCodeInputProps,
    postalCodeStatus
    // Picking a province clears the levels below it, which must not show errors before a submit.
  } = useViraAddress({ form, names: ADDRESS_NAMES, shouldValidate: isSubmitted })

  const onSubmit = form.handleSubmit(async (input) => {
    try {
      onSaved(await saveAddress.mutateAsync({ input, id: address?.id }))
    } catch {
      form.setError("root.server", { message: t("save_error") })
    }
  })

  // The mask reports a key such as `phone.incomplete`, for the form to word.
  const phoneError = errors.phone?.message?.startsWith("phone.")
    ? t("error_phone_invalid")
    : errors.phone?.message

  return (
    <form onSubmit={onSubmit} noValidate className="flex flex-col gap-4">
      <div className="grid gap-4 sm:grid-cols-2">
        <FormField name="firstName" label={t("field_first_name")} error={errors.firstName?.message}>
          <Input
            id="firstName"
            autoComplete={`${type} given-name`}
            aria-invalid={Boolean(errors.firstName)}
            aria-describedby={errors.firstName ? "firstName-error" : undefined}
            {...form.register("firstName")}
          />
        </FormField>
        <FormField name="lastName" label={t("field_last_name")} error={errors.lastName?.message}>
          <Input
            id="lastName"
            autoComplete={`${type} family-name`}
            aria-invalid={Boolean(errors.lastName)}
            aria-describedby={errors.lastName ? "lastName-error" : undefined}
            {...form.register("lastName")}
          />
        </FormField>
      </div>
      <FormField name="phone" label={t("field_phone")} error={phoneError}>
        <Input
          {...phone}
          id="phone"
          autoComplete={`${type} tel-national`}
          aria-invalid={Boolean(errors.phone)}
          aria-describedby={errors.phone ? "phone-error" : undefined}
        />
      </FormField>
      <FormField name="addressLine" label={t("field_line")} error={errors.addressLine?.message}>
        <Textarea
          id="addressLine"
          rows={3}
          autoComplete={`${type} street-address`}
          aria-invalid={Boolean(errors.addressLine)}
          aria-describedby={errors.addressLine ? "addressLine-error" : undefined}
          {...form.register("addressLine")}
        />
      </FormField>
      <div className="grid gap-4 sm:grid-cols-2">
        <AddressSelect
          name="province"
          label={t("field_province")}
          placeholder={t("placeholder_province")}
          autoComplete={`${type} address-level1`}
          error={errors.province?.message}
          options={provinces}
          selectProps={getProvinceProps({ as: "shadcn" })}
        />
        <AddressSelect
          name="district"
          label={t("field_district")}
          placeholder={t("placeholder_district")}
          autoComplete={`${type} address-level2`}
          error={errors.district?.message}
          options={districts}
          selectProps={getDistrictProps({ as: "shadcn" })}
        />
        <AddressSelect
          name="neighbourhood"
          label={t("field_neighbourhood")}
          placeholder={t("placeholder_neighbourhood")}
          autoComplete={`${type} address-level3`}
          error={errors.neighbourhood?.message}
          options={neighbourhoods}
          selectProps={getNeighbourhoodProps({ as: "shadcn" })}
        />
        <FormField
          name="postalCode"
          label={t("field_postal_code")}
          error={
            postalCodeStatus === "unknown" ? t("postal_code_unknown") : errors.postalCode?.message
          }
        >
          <Input
            {...getPostalCodeInputProps({ placeholder: "34710" })}
            id="postalCode"
            inputMode="numeric"
            autoComplete={`${type} postal-code`}
            aria-invalid={postalCodeStatus === "unknown" || Boolean(errors.postalCode)}
            aria-describedby={
              postalCodeStatus === "unknown" || errors.postalCode ? "postalCode-error" : undefined
            }
          />
        </FormField>
      </div>
      <FormField name="addressName" label={t("field_title")} error={errors.addressName?.message}>
        {/* A label for this list, not part of the address, so autofill must leave it empty. */}
        <Input
          id="addressName"
          autoComplete="off"
          aria-invalid={Boolean(errors.addressName)}
          aria-describedby={errors.addressName ? "addressName-error" : undefined}
          {...form.register("addressName")}
        />
      </FormField>
      <Controller
        name="isDefault"
        control={form.control}
        render={({ field }) => (
          <Label className="flex items-center gap-2 font-normal">
            <Checkbox checked={field.value} onCheckedChange={field.onChange} />
            {t("field_default")}
          </Label>
        )}
      />
      <Controller
        name="addressType"
        control={form.control}
        render={({ field }) => (
          <Field>
            <FieldLabel id="addressType-label">{t("field_type")}</FieldLabel>
            <RadioGroup
              aria-labelledby="addressType-label"
              className="flex flex-wrap gap-6"
              value={field.value}
              onValueChange={(value) => {
                field.onChange(value)
                // A hidden field must not keep a value that fails, with no error in sight.
                if (value === "individual") {
                  form.setValue("companyName", "")
                  form.setValue("taxNumber", "")
                  form.setValue("taxOffice", "")
                  form.clearErrors(["companyName", "taxNumber", "taxOffice"])
                }
              }}
            >
              {ADDRESS_TAX_TYPES.map((value) => (
                <Label key={value} className="flex items-center gap-2 font-normal">
                  <RadioGroupItem value={value} />
                  {t(`type_${value}`)}
                </Label>
              ))}
            </RadioGroup>
          </Field>
        )}
      />
      {addressType === "corporate" ? <CorporateFields form={form} type={type} /> : null}
      {errors.root?.server ? (
        <p role="alert" className="text-sm text-destructive">
          {errors.root.server.message}
        </p>
      ) : null}
      <Button type="submit" className="self-start" disabled={isSubmitting}>
        {isSubmitting ? t("saving") : t("save")}
      </Button>
    </form>
  )
}

type CorporateFieldsProps = {
  form: UseFormReturn<AddressFormInput>
  type: AddressType
}

/** Its own component, so the mask registers the tax number after the fields above it on screen. */
function CorporateFields({ form, type }: CorporateFieldsProps) {
  const t = useTranslations("CheckoutAddress")
  const { errors } = form.formState
  form.register("companyName")
  const { taxNumber } = useViraMask(form, TAX_MASKS)
  const taxNumberError = errors.taxNumber?.message?.startsWith("vkn.")
    ? t("error_tax_number_invalid")
    : errors.taxNumber?.message

  return (
    <div className="flex flex-col gap-4">
      <FormField name="companyName" label={t("field_company")} error={errors.companyName?.message}>
        <Input
          id="companyName"
          autoComplete={`${type} organization`}
          aria-invalid={Boolean(errors.companyName)}
          aria-describedby={errors.companyName ? "companyName-error" : undefined}
          {...form.register("companyName")}
        />
      </FormField>
      <div className="grid gap-4 sm:grid-cols-2">
        <FormField name="taxNumber" label={t("field_tax_number")} error={taxNumberError}>
          <Input
            {...taxNumber}
            id="taxNumber"
            autoComplete="off"
            aria-invalid={Boolean(errors.taxNumber)}
            aria-describedby={errors.taxNumber ? "taxNumber-error" : undefined}
          />
        </FormField>
        <FormField name="taxOffice" label={t("field_tax_office")} error={errors.taxOffice?.message}>
          <Input
            id="taxOffice"
            autoComplete="off"
            aria-invalid={Boolean(errors.taxOffice)}
            aria-describedby={errors.taxOffice ? "taxOffice-error" : undefined}
            {...form.register("taxOffice")}
          />
        </FormField>
      </div>
    </div>
  )
}

type FormFieldProps = {
  name: string
  label: string
  error?: string
  children: ReactNode
}

function FormField({ name, label, error, children }: FormFieldProps) {
  return (
    <Field data-invalid={Boolean(error)}>
      <FieldLabel htmlFor={name}>{label}</FieldLabel>
      {children}
      {error ? <FieldError id={`${name}-error`}>{error}</FieldError> : null}
    </Field>
  )
}

type AddressSelectProps = {
  name: string
  label: string
  placeholder: string
  autoComplete: string
  error?: string
  options: readonly { value: string; label: string }[]
  selectProps: ReturnType<ReturnType<typeof useViraAddress>["getProvinceProps"]>
}

function AddressSelect({
  name,
  label,
  placeholder,
  autoComplete,
  error,
  options,
  selectProps
}: AddressSelectProps) {
  return (
    <FormField name={name} label={label} error={error}>
      <Select {...selectProps} name={name} autoComplete={autoComplete} items={options}>
        <SelectTrigger
          id={name}
          className="w-full"
          aria-invalid={Boolean(error)}
          aria-describedby={error ? `${name}-error` : undefined}
        >
          <SelectValue placeholder={placeholder} />
        </SelectTrigger>
        <SelectContent>
          {options.map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </FormField>
  )
}

"use client"

import { useState } from "react"

import { ArrowLeftIcon, PlusIcon } from "lucide-react"
import { useTranslations } from "next-intl"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { AddressDetails } from "@/features/checkout-address/components/AddressDetails"
import { AddressForm } from "@/features/checkout-address/components/AddressForm"
import type { Address, AddressType } from "@/features/checkout-address/schemas/address.schema"

type AddressPickerProps = {
  type: AddressType
  isOpen: boolean
  onOpenChange: (isOpen: boolean) => void
  addresses: Address[]
  selectedId: number | null
  onSelect: (id: number) => void
}

export function AddressPicker({ isOpen, onOpenChange, ...props }: AddressPickerProps) {
  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[calc(100dvh-2rem)] max-w-[calc(100vw-2rem)] overflow-y-auto sm:max-w-lg">
        {/* Mounted only while open, so each opening starts from the chosen address. */}
        <AddressPickerContent {...props} onClose={() => onOpenChange(false)} />
      </DialogContent>
    </Dialog>
  )
}

type AddressPickerContentProps = Omit<AddressPickerProps, "isOpen" | "onOpenChange"> & {
  onClose: () => void
}

function AddressPickerContent({
  type,
  addresses,
  selectedId,
  onSelect,
  onClose
}: AddressPickerContentProps) {
  const t = useTranslations("CheckoutAddress")
  const [draftId, setDraftId] = useState(selectedId)
  /** `undefined` shows the list, `null` an empty form, an address the filled form. */
  const [formTarget, setFormTarget] = useState<Address | null | undefined>(
    addresses.length === 0 ? null : undefined
  )

  if (formTarget !== undefined) {
    return (
      <>
        <DialogHeader>
          <DialogTitle>{formTarget ? t("form_edit_title") : t("form_add_title")}</DialogTitle>
          <DialogDescription>{t("dialog_description")}</DialogDescription>
        </DialogHeader>
        {addresses.length > 0 ? (
          <Button
            variant="ghost"
            size="sm"
            className="justify-self-start"
            onClick={() => setFormTarget(undefined)}
          >
            <ArrowLeftIcon aria-hidden />
            {t("back")}
          </Button>
        ) : null}
        <AddressForm
          key={formTarget?.id ?? "new"}
          type={type}
          address={formTarget}
          onSaved={(saved) => {
            if (formTarget) {
              setDraftId(saved.id)
              setFormTarget(undefined)
            } else {
              onSelect(saved.id)
              onClose()
            }
          }}
        />
      </>
    )
  }

  return (
    <>
      <DialogHeader>
        <DialogTitle>{t("picker_title")}</DialogTitle>
      </DialogHeader>
      <RadioGroup
        aria-label={t("picker_title")}
        value={String(draftId)}
        onValueChange={(value) => setDraftId(Number(value))}
      >
        {addresses.map((address) => (
          <div
            key={address.id}
            className="flex items-start gap-3 rounded-lg border p-4 has-data-checked:border-foreground/40 has-data-checked:bg-muted/40"
          >
            <Label className="flex min-w-0 flex-1 cursor-pointer items-start gap-3 font-normal">
              <RadioGroupItem value={String(address.id)} className="mt-0.5" />
              <AddressDetails address={address} />
            </Label>
            <Button
              variant="ghost"
              size="sm"
              className="shrink-0"
              aria-label={t("edit_label", { title: address.addressName })}
              onClick={() => setFormTarget(address)}
            >
              {t("edit")}
            </Button>
          </div>
        ))}
      </RadioGroup>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <Button variant="outline" onClick={() => setFormTarget(null)}>
          <PlusIcon aria-hidden />
          {t("add_new")}
        </Button>
        <Button
          disabled={draftId === null}
          onClick={() => {
            if (draftId !== null) onSelect(draftId)
            onClose()
          }}
        >
          {t("use_address")}
        </Button>
      </div>
    </>
  )
}

"use client"

import { useState } from "react"

import { useTranslations } from "next-intl"

import { Button } from "@/components/ui/button"
import { AddressDetails } from "@/features/checkout-address/components/AddressDetails"
import { AddressPicker } from "@/features/checkout-address/components/AddressPicker"
import type { Address, AddressType } from "@/features/checkout-address/schemas/address.schema"

type AddressSummaryProps = {
  type: AddressType
  title: string
  addresses: Address[]
  selected: Address | null
  onSelect: (id: number) => void
}

/** Only the chosen address shows on the page; the rest wait in the picker. */
export function AddressSummary({
  type,
  title,
  addresses,
  selected,
  onSelect
}: AddressSummaryProps) {
  const t = useTranslations("CheckoutAddress")
  const [isPickerOpen, setIsPickerOpen] = useState(false)

  return (
    <section aria-label={title} className="flex min-w-0 flex-col gap-3">
      <h3 className="text-lg font-semibold tracking-tight">{title}</h3>
      <div className="flex items-start justify-between gap-3 rounded-lg border p-4">
        {selected ? (
          <AddressDetails address={selected} />
        ) : (
          <p className="text-sm text-muted-foreground">{t("no_address")}</p>
        )}
        <Button
          variant="outline"
          size="sm"
          className="shrink-0"
          aria-label={
            selected ? t("change_label", { title: title }) : t("add_label", { title: title })
          }
          onClick={() => setIsPickerOpen(true)}
        >
          {selected ? t("change") : t("add")}
        </Button>
      </div>
      <AddressPicker
        type={type}
        isOpen={isPickerOpen}
        onOpenChange={setIsPickerOpen}
        addresses={addresses}
        selectedId={selected?.id ?? null}
        onSelect={onSelect}
      />
    </section>
  )
}

import { screen, within } from "@testing-library/react"
import userEvent from "@testing-library/user-event"
import type { UserEvent } from "@testing-library/user-event"
import { http, HttpResponse } from "msw/http"
import { beforeEach, describe, expect, it, vi } from "vitest"

import { siteConfig } from "@/config/site.config"

import { getAddresses } from "@/features/checkout-address/api/get-addresses.api"
import { CheckoutAddress } from "@/features/checkout-address/components/CheckoutAddress"
import { ADDRESSES_PATH } from "@/features/checkout-address/constants/addresses.constants"
import { useAddressSelectionStore } from "@/features/checkout-address/stores/address-selection.store"
import { renderWithProviders } from "@/test/render"
import { server } from "@/test/server"

vi.mock("@/features/checkout-address/api/get-addresses.api", { spy: true })

const ADD_URL = `${siteConfig.apiUrl}${ADDRESSES_PATH}/add`
const EDIT_URL = `${siteConfig.apiUrl}${ADDRESSES_PATH}/1`

async function renderAddresses() {
  renderWithProviders(<CheckoutAddress />)
  return screen.findByRole("region", { name: "Shipping address" })
}

async function openPicker(user: UserEvent) {
  await user.click(screen.getByRole("button", { name: "Change Shipping address" }))
  return screen.findByRole("dialog")
}

async function openNewForm(user: UserEvent) {
  const dialog = await openPicker(user)
  await user.click(within(dialog).getByRole("button", { name: "Add new address" }))
}

async function pick(user: UserEvent, label: string, option: string) {
