import { addressesQueryOptions } from "@/features/checkout-address/api/address.queries"

export function useAddresses() {
  const t = useTranslations("CheckoutAddress")
  // The dummy titles are data, so they are worded here. With a real API, remove the `select`.
  const dummyTitles: Record<string, string> = { Home: t("dummy_home"), Work: t("dummy_work") }

  return useQuery({
    ...addressesQueryOptions,
    select: (addresses) =>
      addresses.map((address) => ({
        ...address,
        addressName: dummyTitles[address.addressName] ?? address.addressName
      }))
  })
}

"use client"

import { useAddresses } from "@/features/checkout-address/hooks/use-addresses"
import { useAddressSelectionStore } from "@/features/checkout-address/stores/address-selection.store"

/**
 * What the module gives the next checkout step: the chosen addresses, ready to send.
 * A choice falls back to the default address, then to the first one.
 */
export function useCheckoutAddress() {
  const { data: addresses = [] } = useAddresses()
  const { shippingId, billingId, isBillingSameAsShipping } = useAddressSelectionStore()

  const fallback = addresses.find(({ isDefault }) => isDefault) ?? addresses[0] ?? null
  const shipping = addresses.find(({ id }) => id === shippingId) ?? fallback
  const billing = isBillingSameAsShipping
    ? shipping
    : (addresses.find(({ id }) => id === billingId) ?? shipping)

  return { shipping, billing, isBillingSameAsShipping }
}

"use client"

import { useMutation, useQueryClient } from "@tanstack/react-query"

import { addressKeys } from "@/features/checkout-address/api/query-keys"
import { saveAddress } from "@/features/checkout-address/api/save-address.api"
import type { Address, AddressFormInput } from "@/features/checkout-address/schemas/address.schema"

type SaveAddressVariables = { input: AddressFormInput; id?: number }

/** One default at a time. With a real API, invalidate `addressKeys.all` instead of this. */
function mergeAddress(addresses: Address[] = [], saved: Address) {
  const others = addresses.map((address) =>
    saved.isDefault ? { ...address, isDefault: false } : address
  )
  return addresses.some(({ id }) => id === saved.id)
    ? others.map((address) => (address.id === saved.id ? saved : address))
    : [...others, saved]
}

export function useSaveAddress() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: ({ input, id }: SaveAddressVariables) => saveAddress(input, id),
    onSuccess: (saved) =>
      queryClient.setQueryData<Address[]>(addressKeys.all, (addresses) =>
        mergeAddress(addresses, saved)
      )
  })
}

import type { useTranslations } from "next-intl"
import { z } from "zod"

export const ADDRESS_TAX_TYPES = ["individual", "corporate"] as const

type CorporateField = "companyName" | "taxNumber" | "taxOffice"

/** These fields show, and are required, only on a corporate address. */
function isFilledForType(field: CorporateField) {
  return (input: { addressType: string } & Record<CorporateField, string>) =>
    input.addressType !== "corporate" || input[field].trim().length > 0
}

/** Without this the corporate errors wait until every other field is valid. */
const alwaysCheck = () => true

/** A factory, so validation errors come in the visitor's language. */
export function createAddressFormSchema(t: ReturnType<typeof useTranslations<"CheckoutAddress">>) {
  return z
    .object({
      addressName: z.string().trim().min(1, t("error_title")).max(40, t("error_too_long")),
      firstName: z.string().trim().min(1, t("error_first_name")).max(50, t("error_too_long")),
      lastName: z.string().trim().min(1, t("error_last_name")).max(50, t("error_too_long")),
      phone: z.string().min(1, t("error_phone")),
      addressLine: z.string().trim().min(1, t("error_line")).max(250, t("error_too_long")),
      provinceCode: z.string(),
      province: z.string().min(1, t("error_province")),
      district: z.string().min(1, t("error_district")),
      neighbourhood: z.string().min(1, t("error_neighbourhood")),
      postalCode: z.string().min(1, t("error_postal_code")),
      isDefault: z.boolean(),
      addressType: z.enum(ADDRESS_TAX_TYPES),
      companyName: z.string().trim().max(100, t("error_too_long")),
      taxNumber: z.string(),
      taxOffice: z.string().trim().max(60, t("error_too_long"))
    })
    .refine(isFilledForType("companyName"), {
      path: ["companyName"],
      message: t("error_company"),
      when: alwaysCheck
    })
    .refine(isFilledForType("taxNumber"), {
      path: ["taxNumber"],
      message: t("error_tax_number"),
      when: alwaysCheck
    })
    .refine(isFilledForType("taxOffice"), {
      path: ["taxOffice"],
      message: t("error_tax_office"),
      when: alwaysCheck
    })
}

export const savedAddressSchema = z.object({ id: z.number() })

export type AddressFormInput = z.infer<ReturnType<typeof createAddressFormSchema>>
export type Address = AddressFormInput & { id: number }
export type AddressType = "shipping" | "billing"

import { create } from "zustand"

type AddressSelectionState = {
  /** Only ids: the addresses themselves stay in the Query cache. */
  shippingId: number | null
  billingId: number | null
  isBillingSameAsShipping: boolean
  setShippingId: (id: number) => void
  setBillingId: (id: number) => void
  setIsBillingSameAsShipping: (isSame: boolean) => void
}

// Client-only UI state, so a module-level store is fine.
export const useAddressSelectionStore = create<AddressSelectionState>()((set) => ({
  shippingId: null,
  billingId: null,
  isBillingSameAsShipping: true,
  setShippingId: (shippingId) => set({ shippingId }),
  setBillingId: (billingId) => set({ billingId }),
  setIsBillingSameAsShipping: (isBillingSameAsShipping) => set({ isBillingSameAsShipping })
}))
